def unique_names(items):
    seen = set()
    result = []
    for item in items:
        name = item.strip()
        key = name.casefold()
        if name and key not in seen:
            seen.add(key)
            result.append(name)
    return result

def sum_valid(records, key):
    total = 0
    for record in records:
        value = record.get(key)
        if value is None:
            continue
        try:
            total += int(value)
        except (TypeError, ValueError):
            continue
    return total

from datetime import date

def oldest_date(values):
    parsed = []
    for value in values:
        try:
            parsed.append(date.fromisoformat(value))
        except (TypeError, ValueError):
            continue
    return min(parsed).isoformat() if parsed else None

def get_path(data, path, default=None):
    current = data
    for part in path.split('.') if path else []:
        if not isinstance(current, dict) or part not in current:
            return default
        current = current[part]
    return current

import unittest

def normalize_email(value):
    if not isinstance(value, str):
        raise ValueError('email must be a string')
    result = value.strip().lower()
    if not result:
        raise ValueError('email must not be empty')
    return result

class NormalizeEmailTests(unittest.TestCase):
    def test_normalizes(self):
        self.assertEqual(normalize_email(' A@EXAMPLE.COM '), 'a@example.com')
    def test_empty_raises(self):
        with self.assertRaises(ValueError):
            normalize_email('  ')
    def test_none_raises(self):
        with self.assertRaises(ValueError):
            normalize_email(None)

def should_retry(attempt, max_attempts):
    if attempt < 1 or max_attempts < 1:
        raise ValueError('attempts must be positive')
    return attempt < max_attempts

function compactValues(values) {
  return values.filter(value => {
    if (value === null || value === undefined) return false;
    return typeof value !== 'string' || value.trim() !== '';
  });
}

async function mapSeries(items, asyncFn) {
  const results = [];
  for (let i = 0; i < items.length; i += 1) {
    results.push(await asyncFn(items[i], i));
  }
  return results;
}

function sumValues(values) {
  return values.reduce((sum, value) => sum + value, 0);
}

def chunks(items, size):
    if size < 1:
        raise ValueError('size must be >= 1')
    return [items[i:i + size] for i in range(0, len(items), size)]

def is_success(response):
    if not isinstance(response, dict):
        return False
    status = response.get('status')
    return isinstance(status, int) and not isinstance(status, bool) and 200 <= status < 300
